float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

code.fragment:
float4 frag(UPEInput i)
{
    float u = i.uv.x;
    float v = i.uv.y;
    float head = i.custom.x;
    float life = 1.0 - i.color.a;
    float eat = saturate((life - _Eat) / max(1.0 - _Eat, 0.001));
    float tailS = max(head - _Tail, eat * 1.02);
    float k = saturate((u - tailS) / max(head - tailS, 0.001));
    float m = smoothstep(0.0, 0.15, k) * (1.0 - smoothstep(head - 0.02, head + 0.01, u)) * step(tailS, u);
    float band = smoothstep(1.0 - _Width, 1.0 - _Width * 0.6, v) * (1.0 - smoothstep(0.9, 1.0, v));
    float2 p = float2(u * _Freq, v * _Freq * 0.5 - i.time * 3.0);
    float2 dir = float2(vnoise(p) - 0.5, vnoise(p + float2(13.1, 4.7)) - 0.5) * 2.0;
    return float4(dir, 0.0, saturate(m * band * (1.0 - life)));
}
